Float BalanceHeuristic(int nf, Float fPdf, int ng, Float gPdf) {
    if (std::isnan(fPdf) || std::isnan(gPdf) || std::isinf(fPdf) || std::isinf(gPdf)) {
        return 0;
    }
    Float f = nf * fPdf;
    Float g = ng * gPdf;
    Float denominator = f + g;

    if (denominator == 0) {
        return 0;
    }
    return f / denominator;
}

